-- Миграция 016: защищённая база знаний с полным гайдом по приложению
-- (категория protected=true — удалить её не может никто, даже управляющий,
-- см. политики knowledge_cat_delete/knowledge_delete в migrations_015.sql).
with cat as (
  insert into knowledge_cat (venue_id, name, protected) values ('e58bb6aa-8a0e-4697-9ef6-0bc001f0e21e', 'Как пользоваться приложением', true)
  returning id
)
insert into knowledge (venue_id, cat_id, title, blocks)
select 'e58bb6aa-8a0e-4697-9ef6-0bc001f0e21e', cat.id, v.title, v.blocks from cat, (values
  ('Стойка', '[{"t": "text", "v": "На «Стойке» видны только вкусы, которые сейчас выставлены для гостей. Найди вкус поиском сверху и нажми «На стойку», чтобы добавить.\n\nУ каждого вкуса на стойке доступны действия:\n• «В стоп-лист» / «Вернуть из стопа» — временно скрыть вкус от гостей (например, кончается заправка), не убирая со стойки.\n• «В неликвид» / «Снять неликвид» — пометить вкус как залежавшийся, чтобы предлагать его гостям в первую очередь.\n• «Убрать со стойки» — вкус уходит со стойки, но остаётся на складе.\n\nВажно: на Стойке вес банки не показывается — табак переставляют между банками, за стойкой вес ненадёжен. Граммовку смотри на Складе."}]'::jsonb),
  ('Склад', '[{"t": "text", "v": "«Склад» показывает все вкусы, которые есть в наличии (в штуках банок), а не только выставленные на стойку.\n\nДействия у вкуса:\n• «Пополнить» — добавить банки на склад (например, пришла поставка).\n• «Списать» — списать банки (бой, порча и т.д.).\n• «Удалить позицию» — полностью убрать вкус из каталога (доступно управляющему).\n\nУправляющий может добавить новую позицию кнопкой «+ Добавить новую позицию» наверху списка.\n\nФильтр «Мало» показывает вкусы, которых остался 1 шт. или меньше — удобно для заказа поставки."}]'::jsonb),
  ('Заказ и Контрагенты', '[{"t": "text", "v": "Вкладка «Заказ» переключается между двумя режимами сверху: «Заказ» и «Контрагенты».\n\nВ режиме «Заказ» собирается список того, что нужно заказать у поставщика: вкусы добавляются из Стоп-листа («Добавить всё в заказ») или из Пожеланий гостей («В заказ»), количество можно поменять.\n\nВ режиме «Контрагенты» — список поставщиков с типами (кальянный, бар, другое), их контакты и файлы (прайсы, договоры) через ту же защищённую базу хранения файлов."}]'::jsonb),
  ('Стоп-лист', '[{"t": "text", "v": "«Стоп-лист» — вкусы, которые временно нельзя предлагать гостям (например, заканчивается заправка), но физически они могут быть на стойке.\n\n«+ Добавить позицию» — найти вкус и поставить в стоп. Управляющий может сразу отправить весь стоп-лист в заказ кнопкой «Добавить всё в заказ».\n\nВернуть вкус гостям обратно — кнопка «Вернуть из стопа»."}]'::jsonb),
  ('Неликвид', '[{"t": "text", "v": "«Неликвид» — вкусы, которые давно не берут (от 30 дней без движения по журналу склада). Приложение само предлагает кандидатов в разделе «Похоже на неликвид» — нажми на вкус и подтверди «В неликвид».\n\nПока вкус в неликвиде, его стоит предлагать гостям в первую очередь — так и написано прямо на странице.\n\nЕсли вкус закончился и на стойке, и на складе — он попадает в «Закончился везде», оттуда можно «Вывести» его из каталога совсем (из базы он не удаляется, просто скрывается из текущих списков)."}]'::jsonb),
  ('Граммовка', '[{"t": "text", "v": "На странице «Граммовка» для каждого вкуса (или сразу для всей линейки бренда) указывается размер банки в граммах — через выпадающий список или вручную.\n\nЭтот размер подтягивается в Заказ, на Склад и в Инвентаризацию рядом с названием вкуса. На самой Стойке вес не показывается специально — там табак часто переставляют между банками, и вес там ненадёжен.\n\nЕсли один и тот же вкус продаётся в двух разных банках одновременно — это считается раздельными позициями склада; на стойке/в заказе они показываются одной строкой с весами через «+», а на складе и в инвентаризации — раздельно."}]'::jsonb),
  ('Крепость табаков', '[{"t": "text", "v": "Крепость задаётся по шкале от 1 до 10 — для каждого вкуса отдельно или сразу для всей линейки. Рядом показывается словесная подсказка (лёгкая / ниже средней / средняя / выше средней / крепкая / очень крепкая).\n\nЭта крепость используется и в гостевой карте, и при подборе миксов — изменения применяются сразу."}]'::jsonb),
  ('Инвентаризация', '[{"t": "text", "v": "«Инвентаризация» помогает сверить фактический остаток табака с тем, что записано в системе, и считает недостачу в рублях.\n\nКатегории товаров:\n• Обычные — цена для расчёта недостачи по умолчанию 8 ₽/г.\n• Хука сигар — только бренд Kraken, кроме линеек Medium Seco и Strong Ligero (они считаются обычными). Цена вписывается вручную.\n• Парфюм (Deus Perfume) — цена вписывается вручную.\nОстальные бренды (Jent Cigar, Bonche, Dogma) считаются обычными.\n\nПри сверке впиши фактический вес — система сама посчитает расхождение по каждому вкусу."}]'::jsonb),
  ('Смена', '[{"t": "text", "v": "Раздел «Смена» показывает, что сейчас выставлено на стойке, и сколько всего штук — удобно для быстрой проверки перед сменой/после смены без переключения на полную Стойку."}]'::jsonb),
  ('Журнал', '[{"t": "text", "v": "«Журнал» — полная история движений склада: что взяли на стойку, что пополнили, что списали, результаты инвентаризации.\n\nФильтры сверху: Все / Взяты на стойку / Пополнения / Списания / Инвентаризация. В фильтре «Списания» дополнительно показывается итоговое количество списанного за всё время."}]'::jsonb),
  ('Альбом миксов', '[{"t": "text", "v": "«Альбом миксов» — подборка готовых миксов табака. Можно посмотреть состав и крепость микса (которая считается по крепости входящих в него вкусов на странице «Крепость табаков»)."}]'::jsonb),
  ('Пожелания гостей', '[{"t": "text", "v": "Этот раздел собирает то, что гости просят через гостевую карту (кнопка «Хочу, чтобы был»). Число слева от вкуса — сколько гостей попросили.\n\nСтатусы: «Просят сейчас» → «В заказе» (после нажатия «В заказ» вкус попадает в список заказа поставщику) → «Добавлено» (после нажатия «Пришло», когда вкус завезли). Из любого статуса можно «Вернуть» обратно в «Просят сейчас» или удалить кнопкой ✕."}]'::jsonb),
  ('Чек-лист смены', '[{"t": "text", "v": "«Чек-лист смены» — повторяющиеся дела: ежедневные или по определённому дню недели. На сегодня показываются только актуальные на сегодня дела, остальные — ниже в «Другие дни».\n\nКогда сотрудник отмечает галочку, рядом сразу пишется, кто и во сколько это сделал — специально без зачёркивания текста, чтобы было видно и имя.\n\nУправляющий добавляет новое дело снизу: вводит текст, выбирает «Каждый день» или «По дню недели» (и день недели), жмёт «+ Добавить дело». Удалить дело — кнопка ✕ рядом с ним."}]'::jsonb),
  ('Команда', '[{"t": "text", "v": "В «Команде» управляющий приглашает новых мастеров кнопкой «+ Пригласить мастера» и настраивает права доступа каждого сотрудника — что ему разрешено делать в приложении (брать на стойку, пополнять склад, работать со стоп-листом и т.д.)."}]'::jsonb),
  ('База знаний: как пользоваться', '[{"t": "text", "v": "«База знаний» — это и есть то, что ты сейчас читаешь. Здесь два уровня: сначала список баз (руководств), внутри каждой — список разделов.\n\nУправляющий может создать новую базу кнопкой «+ Добавить базу», переименовать базу или удалить её через «⋯» в заголовке базы — кроме защищённых баз (как эта): у них кнопки удаления нет вообще, ни в интерфейсе, ни на уровне базы данных. Удалить такую базу не может никто, даже управляющий.\n\nВнутри базы разделы редактируются простым растущим списком блоков: пишешь текст, при необходимости жмёшь «+ Фото», чтобы вставить картинку в нужное место, и продолжаешь писать дальше. Фото показываются уменьшенными превью, а по нажатию открываются крупно прямо в приложении (не в браузере)."}]'::jsonb)
) as v(title, blocks);
